      const notes = el.ownerDocument?.querySelector?.("#speakernotes-workspace");
      const rect = notes?.getBoundingClientRect?.();
      const visibleNotes = !!rect && rect.width > 20 && rect.height > 12
        && rect.bottom >= 0 && rect.top <= window.innerHeight;
      if (visibleNotes) return true;
