    const cached = STATE.editorProfiles.get(el);
    if (cached && !dynamicProfile) return cached;
    const profile = classifyEditorProfile(el);
    if (!dynamicProfile) STATE.editorProfiles.set(el, profile);
    const previous = dynamicProfile ? STATE.dynamicEditorProfiles.get(el) : cached;
    if (dynamicProfile) STATE.dynamicEditorProfiles.set(el, profile);
