    const adapter = resolveEditorAdapter(editor).siteAdapter;
    const sitePolicy = callSiteAdapterHook(adapter, "shouldDisableOtherSpellCheckers", [editor]);
    if (typeof sitePolicy === "boolean") return sitePolicy;
    if (typeof adapter?.nativeProofing?.suppress === "boolean") return adapter.nativeProofing.suppress;
