  const NOTION_PAGE_ROOT_SELECTOR = "main.notion-frame,div.notion-peek-renderer > div[style*='display: flex']";
  const NOTION_PAGE_EDITOR_PART_SELECTOR = "[data-content-editable-root][contenteditable='true'],div.notranslate[contenteditable='true'],h1[contenteditable='true'],[contenteditable='true'][data-content-editable-leaf='true']";
