      getToolbarAnchor: editor => editor?.closest?.(".cm-scroller") || editor,
      getSummaryAnchor: editor => editor?.closest?.(".cm-scroller") || editor,
      getReplacementText: el => el?.classList?.contains("cm-placeholder") ? "" : null,
