            const end = at + issue.text.length;
            const left = normalizeAnchorText(chunk.text.slice(Math.max(0, at - 24), at));
            const right = normalizeAnchorText(chunk.text.slice(end, end + 24));
            if (left.length + right.length < 12 || !before.endsWith(left) || !after.startsWith(right)) continue;
