    const suggestionWords = /\b(ignore|replace|spelling|grammar|suggestion|correction|ortografia|gramatica|suggeriment|correccio|ortografia)\b/u;
    if (suggestionWords.test(haystack)) return false;
    const systemWords = /\b(download|export|pdf|print|share|open|save|cancel|accept|done|select|choose|tab|sheet|range|descargar|exportar|imprimir|guardar|cancelar|aceptar|selecciona|seleccionar|tria|triar|pestanya|pestanyes|full|fulls|descarrega|descarregar)\b/u;
    if (systemWords.test(haystack)) return true;
