        font: raw.font || "16px Arial",
        fontPx: Number(raw.fontPx) || null,
        measuredWidth: Number(raw.measuredWidth) || null,
        cssScaleX: Number(raw.cssScaleX) || null,
        cssScaleY: Number(raw.cssScaleY) || null,
        baseline: Number(raw.baseline) || null,
