      paragraphSeparator: (annotatedSource.match(/\u2029/gu) || []).length,
      lineSeparator: (annotatedSource.match(/\u2028/gu) || []).length,
      verticalTab: (annotatedSource.match(/\u000b/gu) || []).length,
