          layerId: Number(layer.__clReadLayerId || 0), targetFingerprint: String(layer.__clReadTargetFingerprint || ""),
          layerMode: String(layer.options?.mode || ""), reason,
          liveMarks: layerMarks.length, visibleItems: paintItems.length,
