    const scale = base.width > 2 ? base.width / fullWidth : 1;
    const startAdvance = measureGoogleDocsTextAdvance(chunk.font || "16px Arial", text.slice(0, localStart));
    const endAdvance = measureGoogleDocsTextAdvance(chunk.font || "16px Arial", text.slice(0, localEnd));

